[CmdletBinding()]
param([Parameter(Position=0)][string]$InputPath,[double]$JumpDb=5,[double]$DeviationDb=6,[int]$Top=10,[double]$Interval=0.1,[switch]$Json,[string]$Output,[switch]$Help)
. "$PSScriptRoot/lib/Common.ps1"
if($Help){'loudwalk BETA - turn FFmpeg EBU R128 measurements into a loudness timeline';'Usage: .\loudwalk.ps1 INPUT [-JumpDb DB] [-DeviationDb DB] [-Top N] [-Json]';exit 0};if(-not $InputPath){[Console]::Error.WriteLine('input required');exit 2};Assert-CDLDependencies;if(-not(Test-Path -LiteralPath $InputPath -PathType Leaf)){[Console]::Error.WriteLine("unreadable input: $InputPath");exit 2};$p=(Resolve-Path -LiteralPath $InputPath).Path;$inv=[Globalization.CultureInfo]::InvariantCulture
$lines=& ffmpeg -hide_banner -nostats -i $p -filter_complex 'ebur128=peak=true' -f null - 2>&1;$timeline=@();$integrated=$null;$lra=$null;$seenI=$false;$seenL=$false
foreach($line in $lines){$s="$line";if($s -match ' t:\s*([-0-9.]+).* S:\s*([-0-9.]+)'){ $sv=[double]::Parse($Matches[2],$inv); if($sv -gt -100){$timeline += [pscustomobject]@{time_seconds=[double]::Parse($Matches[1],$inv);short_term_lufs=$sv}} };if($s -match 'Integrated loudness:'){$seenI=$true;continue};if($seenI -and $s -match '^\s*I:\s*([-0-9.]+)'){$integrated=[double]::Parse($Matches[1],$inv);$seenI=$false};if($s -match 'Loudness range:'){$seenL=$true;continue};if($seenL -and $s -match '^\s*LRA:\s*([-0-9.]+)'){$lra=[double]::Parse($Matches[1],$inv);$seenL=$false}}
$vals=@($timeline.short_term_lufs|Sort-Object);$median=$null;if($vals.Count){$m=[int]($vals.Count/2);$median=if($vals.Count%2){$vals[$m]}else{($vals[$m-1]+$vals[$m])/2}};$find=@();$prev=$null;foreach($r in $timeline){if($null -ne $prev -and [math]::Abs($r.short_term_lufs-$prev)-ge $JumpDb){$find+=New-CDLFinding 'abrupt_loudness_transition' "adjacent short-term loudness changed from $prev to $($r.short_term_lufs) LUFS"};if($null -ne $median -and [math]::Abs($r.short_term_lufs-$median)-ge $DeviationDb){$find+=New-CDLFinding 'relative_loudness_outlier' "short-term loudness $($r.short_term_lufs) differs from median $median LUFS"};$prev=$r.short_term_lufs}
$status=if($find.Count){'review'}else{'ok'};$report=[ordered]@{tool='loudwalk';version=$script:CDLVersion;generated_utc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');inputs=@($p);dependencies=Get-CDLVersions;options=[ordered]@{jump_db=$JumpDb;deviation_db=$DeviationDb;top=$Top;interval=$Interval};measurements=[ordered]@{integrated_lufs=$integrated;loudness_range_lu=$lra;median_short_term_lufs=$median;timeline=$timeline};findings=$find;status=$status};Write-CDLReport $report -Json:$Json -Output $Output -Text "loudwalk BETA: integrated=$integrated LUFS median=$median status=$status";if($find.Count){exit 1};exit 0
